func digest(b []byte) string { h := sha256.Sum256(b); return hex.EncodeToString(h[:]) }
func boundPin(b []byte, p pin) error {
    if len(b) != p.Bytes || digest(b) != p.SHA256 { return fmt.Errorf("input identity mismatch: %s", p.Path) }
    return nil
}
func canonical(path string) (string, error) {
    if !filepath.IsAbs(path) || filepath.Clean(path) != path { return "", errors.New("path must be absolute and clean") }
    actual, err := filepath.EvalSymlinks(path)
    if err != nil || actual != path { return "", fmt.Errorf("path is missing or contains symlinks: %s", path) }
    return path, nil
}
func readBounded(path string, limit int) ([]byte, error) {
    if _, err := canonical(path); err != nil { return nil, err }
    fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
    if err != nil { return nil, err }
    f := os.NewFile(uintptr(fd), path); defer f.Close()
    before, err := f.Stat()
    if err != nil || !before.Mode().IsRegular() || before.Size() < 0 || before.Size() > int64(limit) { return nil, errors.New("input is not bounded regular file") }
    data, err := io.ReadAll(io.LimitReader(f, int64(limit)+1))
    if err != nil { return nil, err }
    after, err := f.Stat()
    if err != nil || !sameFileIdentity(before, after) || int64(len(data)) != before.Size() { return nil, errors.New("input changed during descriptor read") }
    named, err := os.Lstat(path)
    if err != nil || !sameFileIdentity(after, named) { return nil, errors.New("input path identity changed") }
    return data, nil
}
// Linux gate: exclude atime because the read itself may update it.
func sameFileIdentity(a, b os.FileInfo) bool {
    x, ok := a.Sys().(*syscall.Stat_t); if !ok { return false }
    y, ok := b.Sys().(*syscall.Stat_t); if !ok { return false }
    return x.Dev==y.Dev && x.Ino==y.Ino && x.Mode==y.Mode && x.Nlink==y.Nlink && x.Uid==y.Uid && x.Gid==y.Gid && x.Rdev==y.Rdev && x.Size==y.Size && x.Mtim==y.Mtim && x.Ctim==y.Ctim
}
func exactFixture(path string) error {
    if _,err:=canonical(path);err!=nil{return err}
    fd,err:=syscall.Open(path,syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK|syscall.O_DIRECTORY,0);if err!=nil{return err}
    f:=os.NewFile(uintptr(fd),path);defer f.Close()
    before,err:=f.Stat();if err!=nil{return err}
    names,err:=f.Readdirnames(3);if err!=nil&&err!=io.EOF{return err}
    if !sameNames(names,[]string{"main.oak","oak.mod"}){return errors.New("fixture membership differs")}
    after,err:=f.Stat();if err!=nil||!sameFileIdentity(before,after){return errors.New("fixture directory changed")}
    named,err:=os.Lstat(path);if err!=nil||!sameFileIdentity(after,named){return errors.New("fixture directory path changed")};return nil
}
func bindInputs(sourceRoot, fixture string) error {
    if err:=exactFixture(fixture);err!=nil{return err}
    for _, p := range sourcePins {
        b, err := readBounded(filepath.Join(sourceRoot, p.Path), artifactLimit)
        if err != nil { return err }; if err = boundPin(b, p); err != nil { return err }
        for _, span := range originalSpans {
            if span.Path != p.Path { continue }
            lines := strings.SplitAfter(string(b), "\n")
            if span.FirstLine < 1 || span.LastLine < span.FirstLine || span.LastLine > len(lines) { return errors.New("source span outside file") }
            part := []byte(strings.Join(lines[span.FirstLine-1:span.LastLine], ""))
            if len(part) != span.Bytes || digest(part) != span.SHA256 { return errors.New("source span identity differs") }
        }
        embedded := stdlib.Prelude
        if p.Module != "" { var ok bool; embedded, ok = stdlib.Packages[p.Module]; if !ok { return errors.New("embedded module missing") } }
        if err = boundPin([]byte(embedded), p); err != nil { return err }
    }
    for _, p := range fixturePins {
        b, err := readBounded(filepath.Join(fixture, p.Path), artifactLimit)
        if err != nil { return err }; if err = boundPin(b, p); err != nil { return err }
    }
    return nil
}

// This guard recognizes only the simple checked AST shapes needed by the six
// functions. It checks extraction scope, not correctness of Oak semantics.
func visit(expr ast.Expression, fn string, found map[string]bool, budget *int, depth int) error {
    *budget = *budget - 1
    if *budget < 0 || depth > 64 { return errors.New("checked AST bound exceeded") }
    descend := func(e ast.Expression) error { return visit(e, fn, found, budget, depth+1) }
    switch e := expr.(type) {
    case *ast.Identifier, *ast.IntegerLiteral, *ast.Boolean:
        if reflect.ValueOf(expr).IsNil() { return errors.New("nil scalar AST node") }
        return nil
    case *ast.InfixExpression:
        if e == nil { return errors.New("nil infix") }
        switch e.Operator { case "+", "-", ">", "<=", "||", "|", "<<": default: return errors.New("unexpected arithmetic operator") }
        if err := descend(e.Left); err != nil { return err }; return descend(e.Right)
    case *ast.IndexExpression:
        if e == nil { return errors.New("nil index") }
        if err := descend(e.Left); err != nil { return err }; return descend(e.Index)
    case *ast.InvocationExpression:
        if e == nil || e.ResolvedMethod != "" { return errors.New("unexpected method invocation") }
        id, ok := e.Function.(*ast.Identifier)
        if !ok || id == nil { return errors.New("indirect invocation refused") }
        if _, ok := calls[id.Value]; ok { found[id.Value] = true } else if id.Value != "len" && id.Value != "u16" && id.Value != "u32" { return fmt.Errorf("unexpected callee %s", id.Value) }
        for _, a := range e.Arguments { if err := descend(a); err != nil { return err } }; return nil
    case *ast.VariantExpression:
        if e == nil || e.Variant == nil { return errors.New("missing variant") }
        if e.Payload == nil { return nil }; return descend(e.Payload)
    case *ast.RecordLiteral:
        if e == nil || e.TypeName == nil || e.Extension != nil || e.Layout != nil || len(e.FieldOrder) != len(e.Fields) { return errors.New("unexpected record shape") }
        seen := map[string]bool{}
        for _, field := range e.FieldOrder {
            if field.Value == nil || reflect.TypeOf(field.Value).Kind() != reflect.Ptr || seen[field.Name] || e.Fields[field.Name] != field.Value { return errors.New("record field map/order mismatch") }; seen[field.Name] = true
            if err := descend(field.Value); err != nil { return err }
        }; return nil
    case *ast.MatchExpression:
        if e == nil || len(e.Arms) != 2 { return errors.New("unexpected match shape") }
        if err := descend(e.Scrutinee); err != nil { return err }
        for _, arm := range e.Arms {
            if arm == nil { return errors.New("nil match arm") }
            switch p := arm.Pattern.(type) {
            case *ast.LiteralPattern:
                if p == nil { return errors.New("nil literal pattern") }; if _, ok := p.Value.(*ast.Boolean); !ok { return errors.New("non-Boolean conditional") }
            case *ast.VariantPattern:
                if p == nil || p.Variant == nil || (p.Variant.Value != "Ok" && p.Variant.Value != "Err") { return errors.New("unexpected variant pattern") }
                b, ok := p.Payload.(*ast.BindingPattern); if !ok || b == nil || b.Name == nil || b.Ascribed != nil { return errors.New("unexpected payload pattern") }
            default: return errors.New("unsupported pattern")
            }
            if err := descend(arm.Body); err != nil { return err }
        }; return nil
    case *ast.BlockExpression:
        if e == nil || e.Block == nil || e.Block.Order != "" || e.Block.DeferredFrom != 0 { return errors.New("unexpected block effects") }
        for _, stmt := range e.Block.Statements {
            switch s := stmt.(type) {
            case *ast.ExpressionStatement:
                if s == nil || s.Discard { return errors.New("discard refused") }; if err := descend(s.Expression); err != nil { return err }
            case *ast.VariableDeclaration:
                if s == nil || fn != endianName || s.Name == nil || s.Name.Value != "value" || s.Measured != nil || s.Threadgroup || s.Section != "" { return errors.New("unexpected local declaration") }
                if err := descend(s.Value); err != nil { return err }
            case *ast.AssignmentStatement:
                if s == nil || fn != endianName || s.Name == nil || s.Name.Value != "value" { return errors.New("nonlocal assignment refused") }
                if err := descend(s.Value); err != nil { return err }
            default: return fmt.Errorf("statement outside reader scope: %T", stmt)
            }
        }; return nil
    default: return fmt.Errorf("expression outside reader scope: %T", expr)
    }
}
func namesOf(m map[string]bool) []string { var out []string; for k := range m { out = append(out, k) }; sort.Strings(out); return out }
func sameNames(a, b []string) bool { aa := append([]string{}, a...); bb := append([]string{}, b...); sort.Strings(aa); sort.Strings(bb); return reflect.DeepEqual(aa, bb) }
func checkedFunctions(program *ast.Program, requested []string) (map[string]*ast.FunctionStatement, error) {
    if program == nil || len(requested) != 3 || !sameNames(requested, roots) { return nil, errors.New("requested root set differs") }
    found := map[string]*ast.FunctionStatement{}
    for _, stmt := range program.Statements {
        f, ok := stmt.(*ast.FunctionStatement); if !ok || f == nil || f.Name == nil { continue }
        if _, wanted := calls[f.Name.Value]; !wanted { continue }
        if found[f.Name.Value] != nil { return nil, errors.New("duplicate checked function") }
        if f.Body == nil || len(f.TypeParams) != 0 || f.Receiver != nil || f.ExternSymbol != "" || f.AsmBacked || f.NativeBacked || f.Kernel || f.Theorem || len(f.Dispatch) != 0 { return nil, errors.New("unexpected checked function metadata") }
        refs := map[string]bool{}; budget := 4096
        if err := visit(f.Body, f.Name.Value, refs, &budget, 0); err != nil { return nil, err }
        if !sameNames(namesOf(refs), calls[f.Name.Value]) { return nil, fmt.Errorf("callee closure differs for %s", f.Name.Value) }
        found[f.Name.Value] = f
    }
    if len(found) != 6 { return nil, errors.New("missing checked root/dependency") }
    return found, nil
}

func profile(raw string) (string, error) {
    if len(raw) > artifactLimit || !utf8.ValidString(raw) || strings.ContainsAny(raw, "\x00\r") || !strings.HasPrefix(raw, rawPrefix) { return "", errors.New("generated prefix/encoding/bound differs") }
    tail := strings.TrimPrefix(raw, rawPrefix)
    if strings.Contains(tail, "set_option") || strings.Contains(tail, "namespace ") || !strings.HasSuffix(tail, "end "+namespace+"\n") { return "", errors.New("extra options/namespace or missing end") }
    prefix := strings.Replace(rawPrefix, "maxRecDepth 65536", "maxRecDepth 2048", 1)
    prefix = strings.Replace(prefix, "maxHeartbeats 4000000", "maxHeartbeats 200000", 1)
    return prefix + tail, nil
}

// Compare only after a separately reviewed generated artifact is frozen. Initial
// Extract is a bootstrap receipt and deliberately makes no drift-pass claim.
func compareProfiled(raw string, committed []byte) error {
    got, err := profile(raw); if err != nil { return err }
    if len(committed) > artifactLimit || got != string(committed) { return errors.New("profiled extraction differs from committed artifact") }
    return nil
}

// Declaration blocks are a finite output-format inventory, not a Lean parser
// or a validation of function-body semantics. Raw bytes remain the authority.
func declarationBlocks(raw string) (map[string]string, error) {
    if _, err := profile(raw); err != nil { return nil, err }
    tail := strings.TrimSuffix(strings.TrimPrefix(raw, rawPrefix), "end "+namespace+"\n")
    blocks := map[string]string{}; current := ""
    for _, line := range strings.SplitAfter(tail, "\n") {
        if line == "" { continue }
        if line[0] != ' ' && line[0] != '\n' && !strings.HasPrefix(line, "instance : Inhabited ") {
            fields := strings.Fields(line)
            if len(fields) < 3 || (fields[0] != "def" && fields[0] != "structure" && fields[0] != "inductive") { return nil, errors.New("unexpected generated declaration") }
            current = fields[1]
            if _, exists := blocks[current]; exists { return nil, errors.New("duplicate generated declaration") }
            blocks[current] = ""
        }
        if current == "" { if strings.TrimSpace(line) != "" { return nil, errors.New("unowned generated text") }; continue }
        blocks[current] += line
    }
    for k, b := range blocks { blocks[k] = strings.TrimRight(b, "\n")+"\n" }
    return blocks, nil
}

func expectedTypes(insts []typechecker.Instantiation) (map[string]string, map[string]string, error) {
    w, rr, wr := modules.Mangle("encoding/reader", "Window"), modules.Mangle("encoding/reader", "RangeRead"), modules.Mangle("encoding/reader", "WordRead")
    re, ee := modules.Mangle("encoding/reader", "Error"), modules.Mangle("endian", "Error")
    payloads := map[string]string{"window":w,"remaining":"u32","take":rr,"read":wr,"endian":"u16"}
    results := map[string]string{}
    for key, payload := range payloads {
        errType := re; if key == "endian" { errType = ee }
        for _, inst := range insts { if inst.ADT == "Result" && reflect.DeepEqual(inst.Args, []string{payload, errType}) {
            if results[key] != "" { return nil,nil,errors.New("duplicate checked Result carrier") }; results[key] = inst.MangledName()
        } }
        if results[key] == "" { return nil,nil,fmt.Errorf("missing checked Result carrier: %s", key) }
        // The existing generic mangler joins argument atoms. Refuse an
        // additional instantiation that aliases a required carrier's spelling.
        for _, inst := range insts {
            if inst.MangledName() == results[key] && (inst.ADT != "Result" || !reflect.DeepEqual(inst.Args, []string{payload, errType})) {
                return nil,nil,errors.New("aliased checked Result carrier")
            }
        }
    }
    types := map[string]string{}
    record := func(name, fields, zero string) { types[name] = "structure "+name+" where\n"+fields+"  deriving Repr, BEq, DecidableEq\ninstance : Inhabited "+name+" := ⟨{ "+zero+" }⟩\n" }
    record(w,"  next : UInt32\n  end_ : UInt32\n","next := (0 : UInt32), end_ := (0 : UInt32)")
    record(rr,"  offset : UInt32\n  length : UInt32\n  rest : "+w+"\n","offset := (0 : UInt32), length := (0 : UInt32), rest := (default : "+w+")")
    record(wr,"  value : UInt16\n  rest : "+w+"\n","value := (0 : UInt16), rest := (default : "+w+")")
    suffix := "  deriving Repr, Inhabited, BEq, DecidableEq\n"
    types[re] = "inductive "+re+" where\n  | InvalidWindow\n  | InsufficientData\n"+suffix
    types[ee] = "inductive "+ee+" where\n  | BufferTooSmall\n"+suffix
    for key, payload := range payloads {
        if payload == "u32" { payload = "UInt32" }; if payload == "u16" { payload = "UInt16" }
        errType := re; if key == "endian" { errType = ee }; name := results[key]
        if types[name] != "" { return nil,nil,errors.New("colliding checked Result name") }
        types[name] = "inductive "+name+" where\n  | Ok (payload : "+payload+")\n  | Err (payload : "+errType+")\n"+suffix
    }
    return types, results, nil
}
func validateGenerated(raw string, types, results map[string]string) (map[string]string, error) {
    blocks, err := declarationBlocks(raw); if err != nil { return nil, err }
    if len(types) != 10 || len(results) != 5 || len(blocks) != 16 { return nil, errors.New("generated function/type inventory differs") }
    for name, expected := range types { if blocks[name] != expected { return nil, fmt.Errorf("generated type shape differs: %s", name) } }
    w := modules.Mangle("encoding/reader", "Window")
    signatures := map[string]string{
        rangeName:"(length : UInt32) (offset : UInt32) (width : UInt32) (fuel : Nat) : Option (Bool) := do",
        windowName:"(src : Array UInt8) (offset : UInt32) (count : UInt32) (fuel : Nat) : Option ("+results["window"]+") := do",
        remainingName:"(state : "+w+") (src : Array UInt8) (fuel : Nat) : Option ("+results["remaining"]+") := do",
        takeName:"(state : "+w+") (src : Array UInt8) (count : UInt32) (fuel : Nat) : Option ("+results["take"]+") := do",
        endianName:"(src : Array UInt8) (offset : UInt32) (fuel : Nat) : Option ("+results["endian"]+") := do",
        readName:"(state : "+w+") (src : Array UInt8) (fuel : Nat) : Option ("+results["read"]+") := do",
    }
    for name, sig := range signatures { if !strings.HasPrefix(blocks[name], "def "+name+" "+sig+"\n") { return nil, fmt.Errorf("missing or changed generated function signature: %s", name) } }
    return blocks, nil
}

// Exact byte spans retain inter-declaration whitespace and explicit instances.
// validateGenerated must already have authenticated the finite declaration set.
func generatedSpan(raw, name string) (int, int, error) {
    starts:=map[int]string{};offset:=len(rawPrefix)
    tail:=strings.TrimSuffix(strings.TrimPrefix(raw,rawPrefix),"end "+namespace+"\n")
    for _,line:=range strings.SplitAfter(tail,"\n") {
        for _,kind:=range []string{"def ","structure ","inductive "} {
            if strings.HasPrefix(line,kind){fields:=strings.Fields(line);if len(fields)<3{return 0,0,errors.New("bad declaration line")};starts[offset]=fields[1]}
        }
        offset+=len(line)
    }
    start:=-1;for off,n:=range starts{if n==name{if start>=0{return 0,0,errors.New("duplicate raw span")};start=off}}
    if start<0{return 0,0,errors.New("missing raw span")};end:=len(raw)-len("end "+namespace+"\n")
    for off:=range starts{if off>start&&off<end{end=off}}
    return start,end,nil
}

func emptyOutput(path string) error {
    if _, err := canonical(path); err != nil { return err }
    f, err := os.Open(path); if err != nil { return err }; defer f.Close()
    st, err := f.Stat(); if err != nil || !st.IsDir() || st.Mode().Perm()!=0700 { return errors.New("output must be a private directory") }
    sys, ok := st.Sys().(*syscall.Stat_t); if !ok || sys.Uid != uint32(os.Getuid()) { return errors.New("output owner differs") }
    entries, err := f.Readdirnames(1); if err != io.EOF || len(entries)!=0 { return errors.New("output is not empty") }; return nil
}
func writeArtifact(dir, name string, b []byte) error {
    if len(b)>artifactLimit { return errors.New("artifact cap exceeded") }
    f, err := os.OpenFile(filepath.Join(dir,name),os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if err!=nil{return err}
    n, err := f.Write(b);if err==nil && n!=len(b){err=io.ErrShortWrite};if err==nil{err=f.Sync()};closeErr:=f.Close();if err!=nil{return err};return closeErr
}

// Extract performs exactly two public Check calls: the explicit checked-scope
// inspection and EmitLeanRoots' own check. The runtime owner bounds the process.
func Extract(sourceRoot, fixture, output string) error {
    if err:=emptyOutput(output);err!=nil{return err}
    if err:=bindInputs(sourceRoot,fixture);err!=nil{return err}
    comp:=compiler.New().WithPackageDir(fixture)
    model,err:=comp.Check().Get();if err!=nil{return err}
    funcs,err:=checkedFunctions(model.Tree.Root,roots);if err!=nil{return err}
    types,results,err:=expectedTypes(model.TypeChecker.ADTInstantiations());if err!=nil{return err}
    raw,err:=comp.EmitLeanRoots(namespace,roots).Get();if err!=nil{return err}
    if len(raw)>artifactLimit{return errors.New("raw extraction cap exceeded")}
    // Preserve the actual generator result even if subsequent profile checks fail.
    if err=writeArtifact(output,"raw.lean",[]byte(raw));err!=nil{return err}
    profiled,err:=profile(raw);if err!=nil{return err}
    blocks,err:=validateGenerated(raw,types,results);if err!=nil{return err}
    if err=bindInputs(sourceRoot,fixture);err!=nil{return err}
    var mapping []map[string]any
    keys:=make([]string,0,len(blocks));for k:=range blocks{keys=append(keys,k)};sort.Strings(keys)
    for _,name:=range keys {
        row:=map[string]any{"name":name,"inventory_block_sha256":digest([]byte(blocks[name])),"inventory_block_bytes":len(blocks[name]),"inventory_block_trailing_newlines_normalized":true}
        start,end,err:=generatedSpan(raw,name);if err!=nil{return err}
        row["raw_start_byte"]=start;row["raw_end_byte_exclusive"]=end;row["raw_span_sha256"]=digest([]byte(raw[start:end]))
        shift:=len(profiled)-len(raw);row["profiled_start_byte"]=start+shift;row["profiled_end_byte_exclusive"]=end+shift
        if span,ok:=originalSpans[name];ok{row["source_span"]=span}else{row["generic_source_span"]=originalSpans["Result"];row["specialization_binding"]=name}
        if f:=funcs[name];f!=nil{row["checked_ast_display_sha256"]=digest([]byte(f.String()));row["checked_ast_display_is_not_original_source"]=true;row["callees"]=calls[name]}
        mapping=append(mapping,row)
    }
    receipt:=map[string]any{"schema_version":1,"status":"extracted_not_proved","tree_requires_outer_authentication":tree,"namespace":namespace,"raw_sha256":digest([]byte(raw)),"profiled_sha256":digest([]byte(profiled)),"raw_bytes":len(raw),"profiled_bytes":len(profiled),"roots":roots,"result_carriers":results,"declarations":mapping,"source_pins":sourcePins,"fixture_pins":fixturePins,"checks":2,"lean_invocations":0,"c_invocations":0}
    body,err:=json.MarshalIndent(receipt,"","  ");if err!=nil{return err};body=append(body,'\n')
    if len(body)>artifactLimit{return errors.New("receipt cap exceeded")}
    if err=writeArtifact(output,"BoundedReaderExtracted.lean",[]byte(profiled));err!=nil{return err}
    return writeArtifact(output,"extraction.json",body)
}
